// identity against the adapter modules, and the source bytes of the adapter and the
// entry are hashed at runtime. A mismatch is an infrastructure failure, never a row.
const SOURCE_ROOT = fileURLToPath(new URL('../', import.meta.url));
function sourceSha256(relativePath: string): string { return createHash('sha256').update(readFileSync(SOURCE_ROOT + relativePath)).digest('hex'); }
