// watchdog: a true hang becomes an 'unsettled' leg before the runner itself aborts.
const ROW_TEST_TIMEOUT_MS = 60_000;
const ROW_WATCHDOG_MS = 10_000;
if (ROW_TEST_TIMEOUT_MS <= ROW_WATCHDOG_MS) throw new Error('R16 infrastructure invalidity: runner timeout must exceed the row watchdog');
