  readonly truncatedFlag: boolean | null;
  readonly wireHits: number;
  /** Status-delay rows: the product's retry-delay timer (delay === the configured retryDelay) and how it ended. */
  readonly retryDelayTimer: { delay: number; disposal: 'cleared' | 'fired' | 'live' } | null;
