// --------------------------------------------------------- contracts --
const TUPLE = (afterHeaders: number, afterParse: number, afterResponse: number, beforeError: number, onAbort: number, retry: Partial<Pick<HookCounts, 'retryBeforeRetry' | 'retryCondition' | 'retryExhausted' | 'retryOnRetry'>> = {}): HookCounts => ({ afterHeaders, afterParse, afterResponse, beforeError, onAbort, onTimeout: 0, retryBeforeRetry: 0, retryCondition: 0, retryExhausted: 0, retryOnRetry: 0, ...retry });
